using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using Object=UnityEngine.Object;
public static class RoomRedesignBuilder {
 [Serializable] public sealed class Layout {public string id,title,purpose;public Item[] items;public string[] disable;public View eye;}
 [Serializable] public sealed class View {public Vector3 position,look,up;}
 [Serializable] public sealed class Item {public string id,kind,material,face;public Vector3 position,size;public float pitch,yaw,roll;public int shelves=4;public bool solid=true;}
 static Transform root,added;static string id;static readonly string AssetRoot="Assets/Contour4/";static Material Mat(string name){return AssetDatabase.LoadAssetAtPath<Material>(AssetRoot+"SharedInstituteStyle/V2_"+(string.IsNullOrEmpty(name)?"enamel":name)+".mat")??throw new Exception("Unknown material "+name);}
 static string PathOf(Transform t){return t.parent?PathOf(t.parent)+"/"+t.name:t.name;}
 static GameObject Box(Transform p,string name,Vector3 pos,Vector3 size,Material mat,bool solid){var o=GameObject.CreatePrimitive(PrimitiveType.Cube);o.name=name;o.transform.SetParent(p,false);o.transform.localPosition=pos;o.transform.localScale=size;o.GetComponent<Renderer>().sharedMaterial=mat;if(!solid)Object.DestroyImmediate(o.GetComponent<Collider>());return o;}
 static void Style(bool light = true){foreach(var r in root.GetComponentsInChildren<Renderer>(true)){var mats=r.sharedMaterials;for(int i=0;i<mats.Length;i++){if(!mats[i])continue;string n=mats[i].name.ToLowerInvariant();string m=null;if(n=="shell"||n=="dock-plug"||n=="shell-enamel"||n=="ceiling-liner"||n=="blue-enamel-cladding")m="plaster";else if(n=="deck"||n=="painted-deck")m="floor";else if(n=="obstacle"||n=="fitout-housing"||n=="instrument-enamel"||n=="cold-cabinet-enamel"||n=="reusable-brown-composite")m="enamel";else if(n=="fitout-worktop"||n=="fitout-steeltrim"||n=="brushed-steel-fittings"||n=="blued-steel-frame")m="ivory";else if(n=="fitout-conduit"||n=="amber-freight-paint")m="brass";else if(n=="fitout-seat"||n=="fitout-darklens"||n=="dark-lab-worktop"||n=="graphite-skirting")m="bakelite";if(m!=null)mats[i]=Mat(m);}r.sharedMaterials=mats;}if(light)foreach(var l in root.GetComponentsInChildren<Light>(true))l.intensity*=.65f;}
 static void Disable(string[] names){if(names==null)return;foreach(var name in names){var matches=root.GetComponentsInChildren<Transform>(true).Where(t=>t.name==name).ToArray();if(matches.Length!=1)throw new Exception("Disable must identify one exact object: "+name+" count="+matches.Length);var t=matches[0];string path=PathOf(t);if(!path.Contains("/Geometry/Obstacles/"))throw new Exception("Only Geometry/Obstacles may be replaced: "+path);t.gameObject.SetActive(false);}}
 static void Make(Item it){if(string.IsNullOrEmpty(it.id)||string.IsNullOrEmpty(it.kind))throw new Exception("Every item requires id and kind");if(it.size.x<=0||it.size.y<=0||it.size.z<=0)throw new Exception("Non-positive size: "+it.id);var g=new GameObject(it.id).transform;g.SetParent(added,false);g.localPosition=it.position;g.localRotation=Quaternion.Euler(it.pitch,it.yaw,it.roll);var s=it.size;var mat=Mat(it.material);bool solid=it.solid;switch(it.kind){
 case "bench":{float thickness=Mathf.Min(.10f,s.y*.16f), leg=Mathf.Min(.12f,s.x*.15f);Box(g,"Empty work surface",new Vector3(0,s.y*.5f-thickness*.5f,0),new Vector3(s.x,thickness,s.z),mat,solid);foreach(float sign in new[]{-1f,1f})Box(g,"Bench frame",new Vector3(sign*(s.x*.5f-leg*.5f),-thickness*.5f,0),new Vector3(leg,s.y-thickness,s.z*.84f),Mat("ivory"),solid);break;}
 case "rack":{float t=Mathf.Min(.10f,s.x*.1f);foreach(float sign in new[]{-1f,1f})Box(g,"Rack upright",new Vector3(sign*(s.x*.5f-t*.5f),0,0),new Vector3(t,s.y,s.z),Mat("enamel"),solid);int n=Mathf.Clamp(it.shelves,2,5);for(int j=0;j<n;j++)Box(g,"Empty shelf "+j,new Vector3(0,-s.y*.5f+.08f+(s.y-.16f)*j/(n-1),0),new Vector3(s.x-2*t+.01f,.06f,s.z-.02f),mat,solid);break;}
 case "machine":{Box(g,"Equipment body",Vector3.zero,s,mat,solid);float angle=it.face=="north"?180:it.face=="east"?-90:it.face=="west"?90:0;bool side=Mathf.Abs(angle)==90;float width=side?s.z:s.x, depth=side?s.x:s.z;var front=new GameObject("Instrument front").transform;front.SetParent(g,false);front.localRotation=Quaternion.Euler(0,angle,0);Box(front,"Instrument fascia",new Vector3(0,s.y*.12f,-depth*.5f-.018f),new Vector3(width*.84f,s.y*.60f,.035f),Mat("bakelite"),false);for(int j=-1;j<=1;j++)Box(front,"Instrument indicator",new Vector3(j*width*.23f,s.y*.22f,-depth*.5f-.04f),new Vector3(width*.14f,s.y*.12f,.02f),Mat("ivory"),false);break;}
 case "instrument-frame":{float post=Mathf.Min(.12f,s.x*.12f);foreach(float sign in new[]{-1f,1f})Box(g,"Frame upright",new Vector3(sign*(s.x*.5f-post*.5f),0,0),new Vector3(post,s.y,s.z),Mat("enamel"),solid);Box(g,"Top crossmember",new Vector3(0,s.y*.5f-.06f,0),new Vector3(s.x,.12f,s.z),Mat("ivory"),solid);Box(g,"Empty work surface",new Vector3(0,-s.y*.12f,0),new Vector3(s.x,.09f,s.z),Mat("ivory"),solid);Box(g,"Fixed instrument face",new Vector3(0,s.y*.24f,s.z*.32f),new Vector3(s.x*.72f,s.y*.28f,.08f),Mat("bakelite"),false);break;} case "drum":{var o=GameObject.CreatePrimitive(PrimitiveType.Cylinder);o.name="Drum casing";o.transform.SetParent(g,false);o.transform.localRotation=Quaternion.Euler(0,0,90);o.transform.localScale=new Vector3(s.y,s.x*.5f,s.z);o.GetComponent<Renderer>().sharedMaterial=mat;Object.DestroyImmediate(o.GetComponent<Collider>());if(solid){var c=o.AddComponent<BoxCollider>();c.size=new Vector3(1,2,1);}break;}
 case "housing":case "pipe":case "marking":Box(g,it.kind,Vector3.zero,s,mat,solid&&it.kind!="marking");break;
 case "wall-panel":{Box(g,"Equipment backplate",Vector3.zero,s,mat,solid);Box(g,"Instrument face",new Vector3(0,0,-s.z*.5f-.02f),new Vector3(s.x*.84f,s.y*.72f,.04f),Mat("bakelite"),false);for(int j=-1;j<=1;j++)Box(g,"Meter",new Vector3(j*s.x*.22f,s.y*.08f,-s.z*.5f-.05f),new Vector3(s.x*.14f,s.y*.18f,.02f),Mat("ivory"),false);break;}
 case "chair":{Box(g,"Seat",new Vector3(0,s.y*.05f,0),new Vector3(s.x,.10f,s.z),mat,solid);Box(g,"Chair pedestal",new Vector3(0,-s.y*.25f,0),new Vector3(.12f,s.y*.5f,.12f),Mat("ivory"),solid);Box(g,"Chair back",new Vector3(0,s.y*.30f,s.z*.45f),new Vector3(s.x*.9f,s.y*.4f,.08f),mat,solid);break;}
 default:throw new Exception("Unsupported kind "+it.kind+" for "+it.id);}}
 static Camera NewCamera(string name,Vector3 eye,Vector3 target,Vector3 up,bool ortho,float size){var c=new GameObject(name).AddComponent<Camera>();c.enabled=false;c.transform.position=eye;c.transform.rotation=Quaternion.LookRotation(target-eye,up);c.fieldOfView=80;c.orthographic=ortho;c.orthographicSize=size;c.nearClipPlane=.03f;c.farClipPlane=180;c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.08f,.09f,.10f);return c;}
 static void Shot(Camera c,string name,bool cut){var rr=root.GetComponentsInChildren<Renderer>(false);var b=rr[0].bounds;foreach(var r in rr)b.Encapsulate(r.bounds);var hide=rr.Where(r=>{var n=PathOf(r.transform).ToLowerInvariant();var q=r.bounds;return cut&&(n.Contains("ceiling")||n.Contains("roof")||((n.Contains("wall")||n.Contains("plug"))&&(q.center.x<b.min.x+1.2f||q.center.z<b.min.z+1.2f)));}).ToArray();foreach(var r in hide)r.forceRenderingOff=true;var rt=new RenderTexture(1600,1000,24);c.targetTexture=rt;c.Render();RenderTexture.active=rt;var t=new Texture2D(1600,1000,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1600,1000),0,0);t.Apply();File.WriteAllBytes("../captures/"+id+"-"+name+".png",t.EncodeToPNG());RenderTexture.active=null;c.targetTexture=null;foreach(var r in hide)r.forceRenderingOff=false;Object.DestroyImmediate(t);Object.DestroyImmediate(rt);}
 static void Build(Layout layout){id=layout.id;var paths=AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Contour4/PreparedModules","Assets/Contour4/Rooms"}).Select(AssetDatabase.GUIDToAssetPath).Where(p=>Path.GetFileNameWithoutExtension(p)==id).ToArray();if(paths.Length!=1)throw new Exception("Prefab not unique: "+id);if(new[]{"calibration-sector","spherical-chamber","mobius-hall"}.Contains(id))throw new Exception("Excluded "+id);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene);RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.44f,.44f,.44f);root=((GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(paths[0]))).transform;var l=new GameObject("Showcase light").AddComponent<Light>();l.type=LightType.Directional;l.intensity=.8f;l.transform.rotation=Quaternion.Euler(48,-35,0);var rr=root.GetComponentsInChildren<Renderer>(false);var b=rr[0].bounds;foreach(var r in rr)b.Encapsulate(r.bounds);var over=NewCamera("Preview overview",b.center+new Vector3(-1,1.5f,-1).normalized*Mathf.Max(b.size.magnitude*1.5f,15),b.center,Vector3.up,true,Mathf.Max(b.size.x,b.size.z)*.8f);float projected=0;foreach(float x in new[]{b.min.x,b.max.x})foreach(float y in new[]{b.min.y,b.max.y})foreach(float z in new[]{b.min.z,b.max.z}){var d=new Vector3(x,y,z)-b.center;projected=Mathf.Max(projected,Mathf.Abs(Vector3.Dot(d,over.transform.up)),Mathf.Abs(Vector3.Dot(d,over.transform.right))/1.6f);}over.orthographicSize=projected*1.12f;Vector3 ep=(layout.eye!=null&&(layout.eye.look-layout.eye.position).sqrMagnitude>.01f)?layout.eye.position:new Vector3(b.min.x+Mathf.Min(b.size.x*.20f,3),1.6f,b.min.z+Mathf.Min(b.size.z*.25f,3));Vector3 look=(layout.eye!=null&&(layout.eye.look-layout.eye.position).sqrMagnitude>.01f)?layout.eye.look:new Vector3(b.center.x,1.4f,b.center.z);if(id=="upper-exit-corridor"&&(layout.eye==null||(layout.eye.look-layout.eye.position).sqrMagnitude<=.01f)){ep=new Vector3(9,1.6f,-6.75f);look=new Vector3(15,2,-6.75f);}if(id=="quarter-turn-bridge"&&(layout.eye==null||(layout.eye.look-layout.eye.position).sqrMagnitude<=.01f)){ep=new Vector3(-1.8f,1.6f,0);look=new Vector3(3,0,0);}if(id=="spiral-corridor"&&(layout.eye==null||(layout.eye.look-layout.eye.position).sqrMagnitude<=.01f)){ep=new Vector3(1.5f,1.6f,0);look=new Vector3(8,2,0);}Vector3 up=layout.eye!=null&&layout.eye.up.sqrMagnitude>.5f?layout.eye.up:Vector3.up;var eye=NewCamera("Preview player",ep,look,up,false,0);eye.enabled=true;Camera second=null;if(id=="right-angle-chambers")second=NewCamera("Preview distribution player",new Vector3(1.6f,-12.3f,-2.7f),new Vector3(1.2f,-11.2f,-6.6f),Vector3.right,false,0);Directory.CreateDirectory("Assets/BaselineScenes");Directory.CreateDirectory("Assets/RedesignScenes");Directory.CreateDirectory("../captures");EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene(),"Assets/BaselineScenes/"+id+".unity");Shot(over,"before-overview",true);Shot(eye,"before-eye",false);if(second)Shot(second,"before-eye-distribution",false);Style();Disable(layout.disable);added=new GameObject("Redesign "+id).transform;added.SetParent(root,false);if(layout.items!=null)foreach(var item in layout.items)Make(item);Physics.SyncTransforms();EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene(),"Assets/RedesignScenes/"+id+".unity");Shot(over,"after-overview",true);Shot(eye,"after-eye",false);if(second)Shot(second,"after-eye-distribution",false);File.WriteAllText("../baselines/"+id+"-build.txt",$"id={id}\ntitle={layout.title}\npurpose={layout.purpose}\nprefab={paths[0]}\nitems={(layout.items==null?0:layout.items.Length)}\nscene=Assets/RedesignScenes/{id}.unity\n");}
 public static void ApplyDecorativeLayout(Transform target, Layout layout){
  root = target;
  Style(false);
  added = new GameObject("Institute finishing").transform;
  added.SetParent(target, false);
  foreach (var item in layout.items.Where(item => !item.solid || item.kind == "marking"))
   Make(item);
 }
 public static void ApplyCalibrationStyle(Transform target){
  root = target;
  Style(false);
  var finishing = new GameObject("Calibration instruments finishing").transform;
  finishing.SetParent(target, false);
  Box(finishing, "Acceptance task light", new Vector3(1.0f,2.42f,-3.80f), new Vector3(1.50f,.16f,1.10f), Mat("ivory"), false);
  Box(finishing, "Acceptance wall support", new Vector3(.45f,2.42f,-3.80f), new Vector3(.45f,.16f,1.10f), Mat("ivory"), false);
  Box(finishing, "Acceptance supply", new Vector3(.72f,2.34f,-3.80f), new Vector3(.95f,.12f,.12f), Mat("brass"), false);
 }
 public static void Single(){string name=File.ReadAllText("../active-id.txt").Trim();Build(JsonUtility.FromJson<Layout>(File.ReadAllText("../layouts/"+name+".json")));}
 public static void All(){foreach(var path in Directory.GetFiles("../layouts","*.json").OrderBy(x=>x))Build(JsonUtility.FromJson<Layout>(File.ReadAllText(path)));}
}
